import {createPlanetPreview} from './planet-preview.js';
import {icon} from './icons.js?v=20261115-evidence-1';
import * as THREE from '../vendor/three.module.js';
import {BODY_SHAPES,loadGlobeDEM} from './globe-science.js';
import {loadEarthEnvironment,loadEarthEventsReference,fetchEarthEvents,loadPlanetEnvironmentContext,loadMarsEnvironmentReference} from './environment-data.js';
import {loadEarthLayerCatalogue,fetchEarthLayer} from './earth-observation-layers.js';
import {escapeHTML as esc} from './icons.js';
const number=(v,n=1)=>Number.isFinite(v)?v.toLocaleString('en-US',{maximumFractionDigits:n,minimumFractionDigits:n}):'Unavailable';
const link=(url,title)=>/^https:\/\//.test(url||'')?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(title)} ↗</a>`:'';
const metric=(label,value,note='')=>`<div class="planet-metric"><span>${esc(label)}</span><strong>${esc(value)}</strong>${note?`<small>${esc(note)}</small>`:''}</div>`;
const recordDetails=(title,data)=>`<details class="planet-record"><summary>${esc(title)}</summary><pre>${esc(JSON.stringify(data,null,2))}</pre></details>`;
function sizeGraphic(){return `<svg viewBox="0 0 660 232" class="planet-size-chart" role="img" aria-label="Reference equatorial sizes on one common scale: Earth 12756.274 km diameter, Mars 6792.380 km, Moon 3474.800 km. Distances are not shown.">${[['earth',108,'#60b8bc'],['mars',342,'#db8858'],['moon',526,'#b7c5cf']].map(([body,x,color])=>{const s=BODY_SHAPES[body],rx=76*s.equatorialRadiusMeters/BODY_SHAPES.earth.equatorialRadiusMeters,ry=76*s.polarRadiusMeters/BODY_SHAPES.earth.equatorialRadiusMeters;return `<ellipse cx="${x}" cy="85" rx="${rx}" ry="${ry}" fill="${color}25" stroke="${color}"/><text x="${x}" y="190" text-anchor="middle" fill="${color}" font-size="15">${s.name}</text><text x="${x}" y="218" text-anchor="middle" fill="#a8bac4" font-size="11">${number(s.equatorialRadiusMeters*2/1000)} km</text>`;}).join('')}</svg>`;}
export function createPlanetDataUI({container,getGlobe,getEarth,onBody,onShowGlobe,onCompare,onSources,getTarget,getAnalysisSpacing,toast}){
  let body='earth',manifest=null,catalogue=null,context=null,dem=null,earthRecord=null,marsRecord=null,eventRecord=null,activeLayer=null,requestSerial=0,environmentAbort=null,layerAbort=null,layerSerial=0,loadPromise=null;
  const q=s=>container.querySelector(s);
  container.innerHTML=`<div class="page-heading"><div><p class="eyebrow">THE DATA BEHIND THE GLOBE</p><h1>Understand the data behind the globe<span>.</span></h1><p class="page-subtitle">Choose a world, see the available evidence, and open it on the map.</p></div></div><div class="planet-body-row"><div class="segmented" aria-label="Choose body">${['earth','moon','mars'].map(body=>'<button data-planet-body="'+body+'" class="'+(body==='earth'?'active':'')+'">'+BODY_SHAPES[body].name+'</button>').join('')}</div><div id="planet-data-status" role="status" aria-live="polite"></div></div><section class="panel planet-hero"><figure><div class="planet-body-preview" id="planet-body-preview"></div><figcaption id="planet-preview-caption">Original agency imagery</figcaption></figure><div id="planet-hero-content"></div></section><h2 class="planet-explore-heading">What can I explore?</h2><div class="planet-explore-grid"><article class="panel"><div class="planet-action-image" id="planet-imagery-thumb"></div><div><h3>Surface imagery</h3><p>See visible landforms and surface features.</p><span class="evidence-small-tag">Historical imagery</span><button class="text-link" id="planet-view-surface">View on globe ↗</button></div></article><article class="panel"><div class="planet-action-image" id="planet-elevation-thumb">${icon('terrain')}</div><div><h3>Elevation</h3><p>Explore broad height differences and terrain shape.</p><span class="evidence-small-tag">Numeric elevation data</span><button class="text-link" id="planet-view-elevation">View elevation ↗</button></div></article><article class="panel"><div class="planet-environment-icon">${icon('temperature')}</div><div><h3>Environmental records</h3><p>Availability depends on location and dataset.</p><span class="evidence-small-tag">Selected areas and labelled references</span><button class="text-link" id="planet-open-environment">Review available records ↗</button></div></article></div><div class="panel planet-scale-note"><p><strong>Global overview and local comparisons use different data scales.</strong> Open the records for resolution, dates and coverage.</p><button class="text-link" id="planet-open-sources">Sources &amp; coverage ↗</button></div><details class="evidence-disclosure" id="planet-technical"><summary>Technical details · coordinates, scale &amp; reference figures</summary><div class="evidence-disclosure-body"><section class="panel planet-panel" id="planet-shape"></section><div class="planet-overview" id="planet-source-cards"></div></div></details><details class="evidence-disclosure" id="planet-environment-details"><summary>Environmental evidence · dated observations &amp; context</summary><div class="evidence-disclosure-body"><section class="panel planet-panel" id="planet-facts"></section><div id="planet-earth-observations"></div><section class="panel planet-panel" id="planet-environment"></section><section class="panel planet-panel hidden" id="planet-events"></section></div></details><div class="evidence-bottom-actions"><button class="text-link" id="planet-return">Back to globe ↗</button><button class="button button-outline" id="planet-compare-return">Back to selected comparison ↗</button></div>`;
  const preview=createPlanetPreview(q('#planet-body-preview'),getGlobe);
  q('#planet-compare-return').onclick=onCompare;q('#planet-open-sources').onclick=()=>onSources?.();
  q('#planet-open-environment').onclick=()=>{const section=q('#planet-environment-details');section.open=true;section.scrollIntoView?.({block:'start',behavior:'smooth'});};
  q('#planet-view-surface').onclick=()=>{onShowGlobe(body);getGlobe()?.setLayer('surface');};
  q('#planet-view-elevation').onclick=()=>{onShowGlobe(body);getGlobe()?.setLayer('elevation');};
  q('#planet-return').onclick=()=>onShowGlobe(body);
  container.querySelectorAll('[data-planet-body]').forEach(button=>button.onclick=()=>{onBody(button.dataset.planetBody);selectBody(button.dataset.planetBody);});
  async function resources(){if(!loadPromise)loadPromise=Promise.all([fetch(new URL('../data/globe-imagery-sources.json',import.meta.url)).then(r=>{if(!r.ok)throw Error('Agency image metadata unavailable.');return r.json();}),loadEarthLayerCatalogue()]).then(([m,c])=>{manifest=m;catalogue=c;}).catch(error=>{loadPromise=null;throw error;});return loadPromise;}
  function renderHero(){const shape=BODY_SHAPES[body],image=manifest?.images.find(i=>i.body===body),source=body==='earth'?'NOAA ETOPO1':body==='mars'?'MOLA':'LOLA';q('#planet-hero-content').innerHTML=`<h2>${shape.name}</h2><p>Explore its surface maps and measured elevation data.</p><div class="planet-hero-metrics">${metric('Diameter','about '+number(shape.equatorialRadiusMeters*2/1000,0)+' km')}${metric('Global elevation source',source)}${metric('Imagery',image?'Historical mosaic':'Unavailable')}</div><div class="planet-hero-sizes">${sizeGraphic()}<p>Relative sizes · distances not shown.<br>Each large preview is fitted to view.</p></div>`;q('#planet-preview-caption').textContent=image?image.provider.split(';')[0]+' · historical mosaic':'Agency image not yet available';q('#planet-imagery-thumb').innerHTML=image?'<img src="'+esc(image.path)+'" alt="Original '+shape.name+' published mosaic">':icon('globe');q('#planet-view-surface').disabled=!image;q('#planet-view-elevation').disabled=!dem;preview.show({body,image,dem});q('.planet-scale-note p').innerHTML='<strong>Global overview uses a 1° elevation grid.</strong> '+(getAnalysisSpacing?'The selected comparison uses '+(getAnalysisSpacing()/1000)+' km spacing. ':'Local comparisons use their own analysis grids. ')+'Output spacing does not establish source accuracy.';
   const host=q('#planet-elevation-thumb');host.innerHTML=icon('terrain');if(dem){const canvas=document.createElement('canvas');canvas.width=dem.width;canvas.height=dem.height;const ctx=canvas.getContext('2d');if(ctx){const pixels=ctx.createImageData(dem.width,dem.height);let min=Infinity,max=-Infinity;for(const h of dem.heightsMeters){min=Math.min(min,h);max=Math.max(max,h);}const low=[24,56,81],mid=[110,182,176],high=[239,225,171];for(let i=0;i<dem.heightsMeters.length;i++){const f=(dem.heightsMeters[i]-min)/(max-min||1),a=f<.5?low:mid,b=f<.5?mid:high,t=f<.5?f*2:(f-.5)*2;for(let c=0;c<3;c++)pixels.data[i*4+c]=a[c]+(b[c]-a[c])*t;pixels.data[i*4+3]=255;}ctx.putImageData(pixels,0,0);canvas.setAttribute('aria-label','Elevation display derived from the 1° numeric global grid');host.innerHTML='';host.append(canvas);}}
  }
  function renderShape(){renderHero();const shape=BODY_SHAPES[body];q('#planet-shape').innerHTML=`<p class="eyebrow">${shape.name.toUpperCase()} · BODY-FIXED COORDINATES</p><h2>Size, coordinates and terrain scale</h2><div class="planet-metrics">${metric('Equatorial radius',number(shape.equatorialRadiusMeters/1000,3)+' km')}${metric('Polar reference radius',number(shape.polarRadiusMeters/1000,3)+' km')}${metric('Globe elevation sampling',dem?'1° · 361 × 181 nodes':'Unavailable')}${metric('Vertical exaggeration','1×','Relief retains its source-derived physical scale')}</div><p>${esc(shape.coordinateConvention)}. ${esc(shape.geometryCaveat)}</p><p class="source-note">${esc(shape.frame)}. Markers are coordinate positions; their symbols are enlarged for readability. The globe does not reproduce current sunlight, clouds or celestial orientation.</p>${link(shape.source,'Reference figure / coordinate documentation')}`;}
  function renderSources(){renderHero();const image=manifest?.images.find(i=>i.body===body),files=dem?.source?.files||[];q('#planet-source-cards').innerHTML=`<article class="panel planet-panel"><p class="eyebrow">ORIGINAL PUBLISHED IMAGERY</p><h2>${esc(image?.product||'Imagery unavailable')}</h2>${image?`<p>${esc(image.provider)}</p><div class="planet-source-image"><img src="${esc(image.path)}" alt="Original published ${BODY_SHAPES[body].name} global map"></div><p>${image.width} × ${image.height} pixels · ${esc(image.acquisitionPeriod)}</p><p>${esc(image.limitations.join(' '))}</p>${link(image.documentationUrl,'Agency product page')} · ${link(image.sourceUrl,'Original image')}${recordDetails('Image registration, original-byte hash and credits',image)}`:'<p>Agency imagery is unavailable. Open the source record or try again later.</p>'}</article><article class="panel planet-panel"><p class="eyebrow">NUMERICAL GLOBAL TERRAIN</p><h2>${body==='earth'?'NOAA ETOPO1':body==='mars'?'NASA MOLA radius & topography':'NASA LOLA lunar topography'}</h2><p>${esc(BODY_SHAPES[body].surfaceMode)}.</p><p>The globe uses a 1° global sample of the source product. Its mesh does not retain the full native resolution. Regional comparisons and Expedition use separate 32 km study areas. Their grid spacing is recorded with each location.</p><p>${body==='earth'?'ETOPO1 includes ice-surface topography and ocean-floor bathymetry. Under oceans this terrain mesh represents the sea floor, not a measured moving water surface. ':''}The elevation colours are a TerraMatch display palette, not original optical colour or temperature.</p><button class="button button-outline" id="planet-show-elevation">View numerical elevation on globe ↗</button>${files.map(f=>link(f.url||f.sourceUrl,f.role||f.name||'Original terrain source')).filter(Boolean).join('<br>')}${recordDetails('DEM provenance, resampling and reference datum',dem?{...dem,heightsMeters:'Omitted here; numeric samples are in the bundled dataset.',radiiMeters:dem.radiiMeters?'Omitted here; numeric radii are in the bundled dataset.':undefined}:{status:'unavailable'})}</article>`;q('#planet-show-elevation').onclick=()=>{onShowGlobe(body);getGlobe()?.setLayer('elevation');};}
  function renderFacts(){const facts=['atmosphere','temperature','weather','water'];q('#planet-facts').innerHTML=`<p class="eyebrow">ENVIRONMENTAL CONTEXT</p><h2>What the evidence can tell us</h2><div class="planet-fact-grid">${facts.map(key=>{const fact=context?.[key];return `<article><span class="planet-data-label">${esc(key)}</span><h3>${esc(fact?.label||'Unavailable')}</h3><p>${esc(fact?.text||'No source record loaded.')}</p></article>`;}).join('')}</div><div class="planet-source-links">${(context?.sources||[]).map(s=>link(s.url,s.title)).join(' · ')}</div><button class="text-link" id="planet-thermal-details">Open mission temperature evidence ↗</button>`;q('#planet-thermal-details').onclick=onCompare;}
  function renderLayerControls(){const root=q('#planet-earth-observations');root.innerHTML=body==='earth'&&catalogue?`<section class="panel planet-panel"><p class="eyebrow">NASA GIBS · DATED EARTH LAYERS</p><h2>See the observations on the globe</h2><div class="planet-layer-form"><label>Observation layer<select id="planet-layer">${catalogue.layers.map(l=>`<option value="${l.id}">${esc(l.title)}</option>`).join('')}</select></label><label>Observation date<input type="date" id="planet-layer-date"></label><button class="button button-primary" id="planet-load-layer">Show on globe ↗</button><button class="button button-outline" id="planet-cancel-layer">Cancel request</button></div><p id="planet-layer-note"></p><div id="planet-layer-legend"></div><p class="source-note" id="planet-layer-status" role="status" aria-live="polite"></p><p class="source-note">The 2048 × 1024 global rendition is a browse map. It cannot provide native-resolution local measurements. An unpainted area may be transparent land or missing observation, depending on the layer; read the NASA legend. No values are inferred from image colours.</p></section>`:'';if(body!=='earth'||!catalogue)return;const update=()=>{const l=catalogue.layers.find(l=>l.id===q('#planet-layer').value);q('#planet-layer-date').value=l.reference.date;q('#planet-layer-date').min=l.time.intervals[0].split('/')[0];q('#planet-layer-date').max=l.time.latestAdvertised;q('#planet-layer-note').innerHTML=esc(l.note)+' '+link(l.documentationUrl,'Product documentation');q('#planet-layer-legend').innerHTML=l.legendPath?`<img class="planet-official-legend" src="${l.legendPath}" alt="Original NASA ${esc(l.title)} colour legend">`:'';q('#planet-layer-status').textContent=`Verified availability through ${l.time.latestAdvertised}. Default ${l.reference.date} is a bundled, dated NASA reference; other available dates request NASA directly.`;};q('#planet-layer').onchange=update;update();q('#planet-load-layer').onclick=loadLayer;q('#planet-cancel-layer').onclick=()=>{layerAbort?.abort();};}
  async function loadLayer(){const id=q('#planet-layer').value,date=q('#planet-layer-date').value,serial=++layerSerial;layerAbort?.abort();layerAbort=new AbortController();const signal=layerAbort.signal,status=q('#planet-layer-status'),button=q('#planet-load-layer');button.disabled=true;status.textContent='Loading the dated NASA map…';try{const result=await fetchEarthLayer(catalogue,id,date,{signal});if(serial!==layerSerial||signal.aborted)return;const url=URL.createObjectURL(result.blob);let texture;try{texture=await new THREE.TextureLoader().loadAsync(url);}finally{URL.revokeObjectURL(url);}if(serial!==layerSerial||signal.aborted){texture.dispose();return;}const globe=getGlobe();if(!globe?.renderer){texture.dispose();throw Error('The data loaded, but this device has no WebGL globe. Source records remain available.');}texture.colorSpace=THREE.SRGBColorSpace;texture.minFilter=THREE.LinearFilter;texture.magFilter=THREE.NearestFilter;texture.generateMipmaps=false;activeLayer=result.metadata;onShowGlobe('earth');globe.setObservationTexture(texture,result.metadata);status.textContent=`${result.metadata.title} · ${date} · ${result.metadata.mode}`;toast(`NASA ${result.metadata.title} · ${date} is on the globe.`);}catch(error){if(serial===layerSerial)status.textContent=signal.aborted?'Map request cancelled. The previous globe layer remains unchanged.':error.message;}finally{if(serial===layerSerial)button.disabled=false;}}
  function renderEarthRecord(record,site){const root=q('#planet-environment');if(!['ready','partial'].includes(record?.status)){root.innerHTML=`<p class="eyebrow">EARTH METEOROLOGY</p><h2>${esc(site.name)}</h2><p role="status">${esc(record?.error?.message||'No environmental data available.')}</p><button class="button button-outline" id="planet-retry-environment">Retry NASA request</button>`;q('#planet-retry-environment').onclick=()=>selectBody('earth');return;}const s=record.summary;root.innerHTML=`<p class="eyebrow">NASA POWER · HISTORICAL MODEL / REANALYSIS</p><h2>${esc(site.name)} · 2025 daily records</h2><p>${number(site.lat,4)}° latitude, ${number(site.lon,4)}° longitude · native grid 0.5° × 0.625°. These values describe the coarse model cell, not every spot in this terrain.</p><div class="planet-metrics">${metric('Mean skin temperature',number(s.meanSkinTemperatureK)+' K',Number.isFinite(s.meanSkinTemperatureK)?number(s.meanSkinTemperatureK-273.15)+' °C':'')}${metric('Mean air temperature at 2 m',number(s.meanAirTemperatureK)+' K',Number.isFinite(s.meanAirTemperatureK)?number(s.meanAirTemperatureK-273.15)+' °C':'')}${metric('Mean wind at 10 m',number(s.meanWindSpeed10mMps,2)+' m/s','Daily means; not gusts or storm detection')}${metric('Mean surface pressure',number(s.meanSurfacePressurePa,0)+' Pa')}${metric('Period precipitation',number(s.totalPrecipitationMm,1)+' mm','Rain/snowfall estimate; not standing water')}</div><label class="field-label" for="planet-weather-day">Inspect a recorded day</label><select id="planet-weather-day">${record.series.map((row,i)=>`<option value="${i}">${row.time}</option>`).join('')}</select><div class="planet-metrics" id="planet-weather-values"></div><p class="source-note">${esc(record.limitations.join(' '))}</p>${link(record.source.requestUrl,'Original NASA POWER response')}<p class="source-note">${esc(record.actualPeriod.start)} – ${esc(record.actualPeriod.end)} · ${esc(record.source.timeStandard)} · retrieved ${esc(record.source.retrievedAt)} · ${esc(record.source.retrievalMode)}</p>${recordDetails('Coverage, units and exact source record',{...record,series:'Daily records are available in the day selector and evidence export.'})}`;const update=()=>{const row=record.series[+q('#planet-weather-day').value];q('#planet-weather-values').innerHTML=metric('Skin',number(row.skinTemperatureK)+' K')+metric('Air at 2 m',number(row.airTemperatureK)+' K')+metric('Wind at 10 m',number(row.windSpeed10mMps,2)+' m/s')+metric('Pressure',number(row.surfacePressurePa,0)+' Pa')+metric('Precipitation',number(row.precipitationMmPerDay,2)+' mm/day');};q('#planet-weather-day').onchange=update;update();}
  async function loadEvents(refresh=false){const serial=requestSerial,button=q('#planet-refresh-events');if(button)button.disabled=true;try{const result=refresh?await fetchEarthEvents({signal:environmentAbort?.signal}):await loadEarthEventsReference({signal:environmentAbort?.signal});if(serial!==requestSerial||body!=='earth')return;eventRecord=result;getGlobe()?.setEvents?.(result);renderEvents();}catch(error){if(serial===requestSerial)q('#planet-events').textContent=error.message;}finally{if(button)button.disabled=false;}}
  function renderEvents(){const root=q('#planet-events');root.classList.toggle('hidden',body!=='earth');if(body!=='earth')return;const r=eventRecord;root.innerHTML=`<p class="eyebrow">NASA EONET · EVENT CATALOGUE</p><h2>Reported severe storms</h2><p>${r?`${esc(r.source?.retrievalMode||'request')} · retrieved ${esc(r.retrievedAt||'unknown')}`:'No catalogue loaded.'}</p><p>Open events from a global 30-day catalogue query. Reported positions are approximate dated points, not current storm footprints or a local all-clear.</p><button class="button button-outline" id="planet-refresh-events">Refresh from NASA</button><p class="source-note" role="status">${r?.error?esc(r.error.message):r?.status==='empty'?'No catalogue entries returned. This does not establish that no storms exist.':r?.possiblyTruncated?'Provider result limit reached; catalogue may be incomplete.':''}</p><div class="planet-events-list">${(r?.events||[]).map((event,i)=>`<article><div><h3>${esc(event.title)}</h3><p>${esc(event.latestGeometry?.date||'No usable position')} · ${esc(event.latestGeometry?.type||'No geometry')}</p>${event.sources.map(s=>link(s.url,s.id||'Original event report')).join(' · ')}</div>${event.latestGeometry?.type==='Point'?`<button class="button button-outline button-small" data-event-focus="${i}">Show reported point ↗</button>`:''}</article>`).join('')}</div>${r?recordDetails('Catalogue query and source provenance',{query:r.query,source:r.source,limitations:r.limitations,events:r.events}):''}`;q('#planet-refresh-events').onclick=()=>loadEvents(true);root.querySelectorAll('[data-event-focus]').forEach(button=>button.onclick=()=>{const g=r.events[+button.dataset.eventFocus].latestGeometry;onShowGlobe('earth');getGlobe()?.focusSite({lat:g.coordinates[1],lon:g.coordinates[0]});toast('Showing a dated catalogue position, not a storm boundary.');});}
  async function selectBody(next=body){if(!BODY_SHAPES[next])return;layerAbort?.abort();layerSerial++;body=next;const serial=++requestSerial;environmentAbort?.abort();environmentAbort=new AbortController();const signal=environmentAbort.signal;container.querySelectorAll('[data-planet-body]').forEach(b=>b.classList.toggle('active',b.dataset.planetBody===body));q('#planet-data-status').textContent='Loading original source records…';dem=null;context=null;renderShape();q('#planet-source-cards').innerHTML='';q('#planet-facts').innerHTML='<p>Loading source facts…</p>';q('#planet-earth-observations').innerHTML='';q('#planet-environment').innerHTML='<p role="status">Loading environmental evidence…</p>';q('#planet-events').classList.toggle('hidden',body!=='earth');try{await resources();const [d,c]=await Promise.all([loadGlobeDEM(body,{signal}),loadPlanetEnvironmentContext(body,{signal})]);if(serial!==requestSerial)return;dem=d;context=c;renderShape();renderSources();renderFacts();renderLayerControls();q('#planet-data-status').textContent=BODY_SHAPES[body].name+' sources loaded · Historical imagery and elevation data';if(body==='earth'){const site={...getEarth()};await Promise.all([loadEarthEnvironment(site,{signal}).then(r=>{if(serial!==requestSerial)return;earthRecord=r;renderEarthRecord(r,site);}),loadEvents()]);}else if(body==='mars'){const r=await loadMarsEnvironmentReference({signal});if(serial!==requestSerial)return;marsRecord=r;q('#planet-environment').innerHTML=`<p class="eyebrow">NASA PDS · PERSEVERANCE MEDA</p><h2>Jezero pressure · sol 29 · reference location</h2><p>${getTarget?.()?.body==='mars'&&getTarget().id!=='jezero'?'This record is from Jezero, not the selected '+esc(getTarget().name)+' area. ':''}Historical rover measurements from ${esc(r.period?.startUTC||'unknown')} to ${esc(r.period?.endUTC||'unknown')}. This is one instrument location and one sol, not weather across Mars.</p><div class="planet-metrics">${Object.entries(r.summary?.channels||{}).map(([id,m])=>metric(id.replace('_PRESSURE','')+' sampled mean',number(m.meanPa,2)+' Pa',`${number(m.validCount,0)} samples · no reported numeric uncertainty`)).join('')}</div><p>Three pressure channels remain separate. The record has 37 occupied half-hour bins and 11 gaps; we do not fill them or infer a dust storm. Open mission temperature evidence for MEDA ground temperatures.</p>${link(r.source?.requestUrl||r.source?.dataUrl||r.source?.url,'Original PDS source')}${recordDetails('Pressure source, sample coverage and limitations',r)}`;}else q('#planet-environment').innerHTML='<p class="eyebrow">LUNAR CONDITIONS</p><h2>Lunar environmental context</h2><p>The Moon’s extremely thin exosphere cannot support Earth-like wind, rain or atmospheric storms. Space weather, radiation and dust transport require separate measurements. Mission temperature evidence includes a Diviner annual-maximum model for the south-polar study window; it is not the current temperature or an ice detection.</p>'; }catch(error){if(serial===requestSerial&&!signal.aborted){q('#planet-data-status').textContent=error.message;q('#planet-environment').textContent='Source data could not be loaded. Try again later or inspect the available source records.';}}}
  return{selectBody,open:preferred=>selectBody(preferred||getGlobe()?.body||body),snapshot:()=>({body,physicalScale:'One metre-to-scene factor for all bodies; camera zoom is independent',globalDEMSamplingDegrees:1,verticalExaggeration:1,imagery:manifest?.images||[],earthEnvironment:earthRecord,marsPressure:marsRecord,earthEvents:eventRecord,globeDisplay:getGlobe()?.metadata()?{body:getGlobe().metadata().body,layer:getGlobe().metadata().layer,scaleMode:getGlobe().metadata().scaleMode,imageDisplay:getGlobe().metadata().imageDisplay}:null,earthObservation:activeLayer?{...activeLayer,visible:getGlobe()?.metadata()?.observation?.id===activeLayer.id}:null}),report:()=>`\n\n## Scientific globe and environmental context\n\nGlobal geometry uses NOAA ETOPO1, NASA MOLA radius, and NASA LOLA at 1-degree sampling, without exaggerated relief. Earth ETOPO1 MSL height is applied to WGS84 with geoid undulation omitted. Imagery is an unchanged historical NASA/USGS provider rendition. Current celestial orientation is not reconstructed.\n\n${earthRecord?`Earth environmental source: ${earthRecord.source.requestUrl}\nPeriod: ${earthRecord.requestedPeriod.start}–${earthRecord.requestedPeriod.end}; ${earthRecord.source.timeStandard}. Historical model/reanalysis, not current weather.\n`:''}${marsRecord?`Mars pressure: MEDA sol 29, ${marsRecord.period?.startUTC}–${marsRecord.period?.endUTC}; separate Barocap channels with unavailable numeric uncertainty.\n`:''}${activeLayer?`Earth observation: ${activeLayer.title}; date ${activeLayer.date}; ${activeLayer.requestUrl}\n`:''}${eventRecord?`EONET query retrieved ${eventRecord.retrievedAt}. Catalogue points are dated approximate reports, not current storm boundaries. ${eventRecord.source?.requestUrl}\n`:''}Local water or ice presence and current Mars dust storms are not inferred from optical imagery. Loaded full source metadata and records are included in the evidence JSON.\n`};
}
